-- PREPARED ONLY: W-01..W-12 separate append-only review for one immutable communication-workspace head.
-- Not applied. It changes no native/Android writer, communication evidence event, care record, visit, measure or employee record.
-- Runtime proof still requires PostgreSQL/PostgREST/RLS/grants, two sessions, CAS/deadlock/rollback,
-- SDK argument names, old-writer compatibility, browser/layout and qualified care/privacy/legal acceptance.
begin;
create schema if not exists communication_evidence_review_private;
revoke all on schema communication_evidence_review_private from public,anon,authenticated;
create table if not exists communication_evidence_review_private.review_scopes(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,employee_id uuid not null,qualification_id uuid not null,kind text not null check(kind='communication_coordination_review'),qualification_fingerprint text not null check(qualification_fingerprint~'^sha256:[0-9a-f]{64}$'),document_fingerprint text not null check(document_fingerprint~'^sha256:[0-9a-f]{64}$'),approved_at timestamptz not null,valid_until timestamptz not null,revoked_at timestamptz,unique(tenant_id,employee_id,qualification_id,kind,approved_at));
create table if not exists public.communication_evidence_review_roots(id uuid primary key,tenant_id uuid not null,communication_head_id uuid not null,communication_kind text not null,communication_fingerprint text not null check(communication_fingerprint~'^sha256:[0-9a-f]{64}$'),created_at timestamptz not null,unique(tenant_id,communication_head_id));
create table if not exists public.communication_evidence_review_events(id uuid primary key,tenant_id uuid not null,root_id uuid not null references public.communication_evidence_review_roots(id),revision integer not null check(revision between 1 and 2),previous_id uuid,request_id uuid not null unique,action text not null check(action in('request','return','accept')),actor_id uuid not null,actor_name text not null,recorded_at timestamptz not null,reason text not null,required_change text not null,rationale text not null,communication_head_id uuid not null,communication_kind text not null,communication_fingerprint text not null,qualification_original jsonb,fingerprint text not null,packet jsonb not null,unique(root_id,revision));
create table if not exists public.communication_evidence_review_receipts(request_id uuid primary key,tenant_id uuid not null,actor_id uuid not null,root_id uuid not null,event_id uuid not null,packet jsonb not null,original jsonb not null,recorded_at timestamptz not null);
alter table communication_evidence_review_private.review_scopes enable row level security;alter table public.communication_evidence_review_roots enable row level security;alter table public.communication_evidence_review_events enable row level security;alter table public.communication_evidence_review_receipts enable row level security;
revoke all on communication_evidence_review_private.review_scopes,public.communication_evidence_review_roots,public.communication_evidence_review_events,public.communication_evidence_review_receipts from public,anon,authenticated;
create or replace function communication_evidence_review_private.review_immutable()returns trigger language plpgsql security definer set search_path='' as $$begin raise exception 'Kommunikationsfachprüfung bleibt unveränderlich.' using errcode='P0S01';end$$;
drop trigger if exists communication_review_roots_immutable on public.communication_evidence_review_roots;create trigger communication_review_roots_immutable before update or delete on public.communication_evidence_review_roots for each row execute function communication_evidence_review_private.review_immutable();
drop trigger if exists communication_review_events_immutable on public.communication_evidence_review_events;create trigger communication_review_events_immutable before update or delete on public.communication_evidence_review_events for each row execute function communication_evidence_review_private.review_immutable();
drop trigger if exists communication_review_receipts_immutable on public.communication_evidence_review_receipts;create trigger communication_review_receipts_immutable before update or delete on public.communication_evidence_review_receipts for each row execute function communication_evidence_review_private.review_immutable();

create or replace function communication_evidence_review_private.review_source(t uuid,a uuid)returns jsonb language sql security definer set search_path='' as $$select communication_evidence_private.read_context(t,a)-'actorId'-'loadedAt'$$;
create or replace function communication_evidence_review_private.review_original(root uuid)returns jsonb language sql security definer set search_path='' as $$
select jsonb_build_object('id',last_e.id::text,'tenantId',r.tenant_id::text,'rootId',r.id::text,'headId',last_e.id::text,'revision',last_e.revision,'communicationHeadId',r.communication_head_id::text,'communicationKind',r.communication_kind,'communicationFingerprint',r.communication_fingerprint,'status',case last_e.action when'request'then'requested'when'return'then'returned'else'accepted'end,'history',coalesce((select jsonb_agg(jsonb_build_object('id',e.id::text,'revision',e.revision,'previousId',e.previous_id::text,'requestId',e.request_id::text,'action',e.action,'recordedAt',to_char(e.recorded_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'actorId',e.actor_id::text,'actorName',e.actor_name,'reason',e.reason,'requiredChange',e.required_change,'rationale',e.rationale,'communicationHeadId',e.communication_head_id::text,'communicationKind',e.communication_kind,'communicationFingerprint',e.communication_fingerprint,'qualification',e.qualification_original,'fingerprint',e.fingerprint)order by e.revision)from public.communication_evidence_review_events e where e.root_id=r.id),'[]'::jsonb))
from public.communication_evidence_review_roots r join lateral(select e.* from public.communication_evidence_review_events e where e.root_id=r.id order by e.revision desc limit 1)last_e on true where r.id=root$$;

create or replace function communication_evidence_review_private.read_review_page(t uuid,actor uuid,cursor_at timestamptz,cursor_id uuid,page_size integer)returns jsonb language plpgsql security definer set search_path='' as $$declare rows jsonb;next_at timestamptz;next_id uuid;begin perform communication_evidence_private.actor(t,actor,null);if page_size<1 or page_size>100 then raise exception 'Seitengröße ist ungültig.' using errcode='22023';end if;with page as(select r.id,e.recorded_at from public.communication_evidence_review_roots r join lateral(select x.recorded_at from public.communication_evidence_review_events x where x.root_id=r.id order by x.revision desc limit 1)e on true where r.tenant_id=t and(cursor_at is null or(e.recorded_at,r.id)<(cursor_at,cursor_id))order by e.recorded_at desc,r.id desc limit page_size)select coalesce(jsonb_agg(communication_evidence_review_private.review_original(id)order by recorded_at desc,id desc),'[]'::jsonb),min(recorded_at),min(id)filter(where recorded_at=(select min(recorded_at)from page))into rows,next_at,next_id from page;return jsonb_build_object('rows',rows,'nextCursorRecordedAt',case when jsonb_array_length(rows)=0 then null else to_char(next_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')end,'nextCursorId',next_id);end$$;

create or replace function communication_evidence_review_private.commit_review(p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$
declare t uuid:=(p->>'tenantId')::uuid;actor uuid:=(p->>'actorId')::uuid;req uuid:=(p->>'requestId')::uuid;action_value text:=p->>'action';expected integer:=(p->>'expectedRevision')::integer;event_ref uuid:=gen_random_uuid();review_root uuid;now_at timestamptz:=clock_timestamp();today date:=(clock_timestamp()at time zone'Europe/Berlin')::date;name text;source jsonb;source_head uuid;source_kind text;source_fingerprint text;prior public.communication_evidence_review_events%rowtype;qualification jsonb;original jsonb;receipt public.communication_evidence_review_receipts%rowtype;fingerprint text;
begin
 if p->>'schemaVersion'<>'1'or action_value not in('request','return','accept')or req is null or t is null or actor is null or expected not between 0 and 1 or jsonb_typeof(p->'communicationOriginal')<>'object'or jsonb_typeof(p->'reason')<>'string'or jsonb_typeof(p->'requiredChange')<>'string'or jsonb_typeof(p->'rationale')<>'string' then raise exception 'Kommunikationsfachprüfanfrage ist unvollständig.' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('communication-workspace-review:'||t::text,0));select*into receipt from public.communication_evidence_review_receipts r where r.request_id=req for update;if found then if receipt.tenant_id<>t or receipt.actor_id<>actor or receipt.packet<>p then raise exception 'Anfragekennung ist anders gebunden.' using errcode='P0S01';end if;return jsonb_build_object('requestId',req::text,'packet',p,'original',receipt.original);end if;
 source:=communication_evidence_review_private.review_source(t,actor);if source is distinct from p->'communicationOriginal' then raise exception 'Vollständiger aktueller Kommunikationsbestand wurde verändert.' using errcode='P0S01';end if;source_head:=(source#>>'{history,headId}')::uuid;source_kind:=source#>>array['history','events',(jsonb_array_length(source#>'{history,events}')-1)::text,'command','kind'];if source_head is null or btrim(coalesce(source_kind,''))='' then raise exception 'Ein gespeicherter Kommunikationsbestand fehlt.' using errcode='23514';end if;source_fingerprint:='sha256:'||encode(extensions.digest(convert_to(source::text,'UTF8'),'sha256'),'hex');
 if action_value='request'then perform communication_evidence_private.actor(t,actor,null);elsif not public.has_permission('pflege.documentation.sign')or not public.has_permission('communication.view_center')or not public.has_permission('integrations.view')or not public.has_permission('ti.view')or not public.has_permission('communication.send_internal_note')then raise exception 'Kommunikationsfachprüfrecht fehlt.' using errcode='42501';end if;
 select coalesce(pr.display_name,pr.email)into name from public.profiles pr where pr.id=actor and pr.tenant_id=t and pr.is_active=true;if btrim(coalesce(name,''))=''then raise exception 'Aktiver Akteur fehlt.' using errcode='42501';end if;
 if action_value='request'then if expected<>0 or p->'expectedHeadId'<>'null'::jsonb or p->'reviewOriginal'<>'null'::jsonb or length(btrim(p->>'reason'))<10 or p->>'requiredChange'<>''or p->>'rationale'<>''then raise exception 'Prüfanfrage darf keine Entscheidung enthalten.' using errcode='23514';end if;review_root:=event_ref;insert into public.communication_evidence_review_roots(id,tenant_id,communication_head_id,communication_kind,communication_fingerprint,created_at)values(review_root,t,source_head,source_kind,source_fingerprint,now_at);
 else review_root:=(p#>>'{reviewOriginal,rootId}')::uuid;perform 1 from public.communication_evidence_review_roots r where r.id=review_root and r.tenant_id=t and r.communication_head_id=source_head and r.communication_kind=source_kind and r.communication_fingerprint=source_fingerprint for update;if not found then raise exception 'Passende unveränderte Kommunikationsprüfanfrage fehlt.' using errcode='P0S01';end if;select*into prior from public.communication_evidence_review_events e where e.root_id=review_root order by e.revision desc limit 1 for update;if not found or expected<>1 or prior.action<>'request'or prior.id::text<>p->>'expectedHeadId'or communication_evidence_review_private.review_original(review_root)is distinct from p->'reviewOriginal'then raise exception 'Kommunikationsprüfanfrage hat sich geändert.' using errcode='P0S01';end if;if actor=prior.actor_id or exists(select 1 from jsonb_array_elements(source#>'{history,events}')e where e->>'actorId'=actor::text)then raise exception 'Anfragende oder am Kommunikationsbestand beteiligte Person darf nicht selbst entscheiden.' using errcode='42501';end if;
  lock table public.employees,public.employee_employment_details,public.employee_qualifications,public.employee_documents,communication_evidence_review_private.review_scopes in share mode;
  select jsonb_build_object('id',q.id::text,'employeeId',e.id::text,'profileId',e.profile_id::text,'qualificationType',q.qualification_type,'title',q.title,'status',q.status,'issuedAt',to_char(q.issued_at,'YYYY-MM-DD'),'validUntil',to_char(q.valid_until,'YYYY-MM-DD'),'verifiedAt',to_char(q.verified_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'updatedAt',to_char(q.updated_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'documentId',d.id::text,'documentFingerprint',scope.document_fingerprint,'qualificationFingerprint',scope.qualification_fingerprint,'employeeFingerprint','sha256:'||encode(extensions.digest(convert_to(jsonb_build_object('employee',to_jsonb(e),'employment',to_jsonb(ed))::text,'UTF8'),'sha256'),'hex'),'scopeId',scope.id::text,'scopeKind','communication_coordination_review','scopeFingerprint','sha256:'||encode(extensions.digest(convert_to(to_jsonb(scope)::text,'UTF8'),'sha256'),'hex'))into qualification from public.employees e join public.employee_employment_details ed on ed.employee_id=e.id and ed.tenant_id=e.tenant_id join public.employee_qualifications q on q.employee_id=e.id and q.tenant_id=e.tenant_id join public.employee_documents d on d.id=q.document_id and d.employee_id=e.id and d.tenant_id=e.tenant_id join communication_evidence_review_private.review_scopes scope on scope.employee_id=e.id and scope.qualification_id=q.id and scope.tenant_id=e.tenant_id and scope.kind='communication_coordination_review'where e.tenant_id=t and e.profile_id=actor and e.status='aktiv'and ed.employment_status='active'and coalesce(e.entry_date,e.start_date)<=today and(e.exit_date is null or e.exit_date>=today)and q.status in('valid','expires_soon')and q.verified_at<=now_at and q.updated_at<=now_at and(q.issued_at is null or q.issued_at<=today)and(q.valid_until is null or q.valid_until>=today)and(d.valid_until is null or d.valid_until>=today)and btrim(coalesce(d.storage_path,''))<>''and scope.approved_at<=now_at and scope.valid_until>now_at and scope.revoked_at is null and scope.qualification_fingerprint='sha256:'||encode(extensions.digest(convert_to(to_jsonb(q)::text,'UTF8'),'sha256'),'hex')and scope.document_fingerprint='sha256:'||encode(extensions.digest(convert_to(to_jsonb(d)::text,'UTF8'),'sha256'),'hex')order by scope.approved_at desc,scope.id desc limit 1;
  if qualification is null then raise exception 'Aktuelle Beschäftigung, Qualifikation, Dokument und Kommunikationsprüfbereich fehlen.' using errcode='42501';end if;if action_value='return'then if length(btrim(p->>'reason'))<10 or length(btrim(p->>'requiredChange'))<10 or p->>'rationale'<>''then raise exception 'Rückgabe benötigt Grund und konkrete Änderung.' using errcode='23514';end if;elsif p->>'reason'<>''or p->>'requiredChange'<>''or length(btrim(p->>'rationale'))<10 then raise exception 'Fachliche Annahme benötigt eine konkrete Begründung.' using errcode='23514';end if;
 end if;
 fingerprint:='sha256:'||encode(extensions.digest(convert_to(jsonb_build_object('packet',p,'qualification',qualification)::text,'UTF8'),'sha256'),'hex');insert into public.communication_evidence_review_events(id,tenant_id,root_id,revision,previous_id,request_id,action,actor_id,actor_name,recorded_at,reason,required_change,rationale,communication_head_id,communication_kind,communication_fingerprint,qualification_original,fingerprint,packet)values(event_ref,t,review_root,expected+1,case when expected=0 then null else prior.id end,req,action_value,actor,name,now_at,p->>'reason',p->>'requiredChange',p->>'rationale',source_head,source_kind,source_fingerprint,qualification,fingerprint,p);original:=communication_evidence_review_private.review_original(review_root);insert into public.communication_evidence_review_receipts(request_id,tenant_id,actor_id,root_id,event_id,packet,original,recorded_at)values(req,t,actor,review_root,event_ref,p,original,now_at);return jsonb_build_object('requestId',req::text,'packet',p,'original',original);
end$$;
create or replace function communication_evidence_review_private.confirm_review(t uuid,actor uuid,req uuid,p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare r public.communication_evidence_review_receipts;begin perform communication_evidence_private.actor(t,actor,null);select*into r from public.communication_evidence_review_receipts x where x.request_id=req and x.tenant_id=t and x.actor_id=actor;if not found or r.packet is distinct from p then raise exception 'Keine passende unveränderliche Kommunikationsfachprüfquittung.' using errcode='P0S03';end if;return jsonb_build_object('requestId',req::text,'packet',r.packet,'original',r.original);end$$;
create or replace function public.web_read_communication_evidence_review_page(p_tenant_id uuid,p_actor_profile_id uuid,p_cursor_recorded_at timestamptz,p_cursor_id uuid,p_page_size integer)returns jsonb language sql security invoker set search_path='' as $$select communication_evidence_review_private.read_review_page(p_tenant_id,p_actor_profile_id,p_cursor_recorded_at,p_cursor_id,p_page_size)$$;
create or replace function public.web_commit_communication_evidence_review(p_packet jsonb)returns jsonb language sql security invoker set search_path='' as $$select communication_evidence_review_private.commit_review(p_packet)$$;
create or replace function public.web_confirm_communication_evidence_review(p_tenant_id uuid,p_actor_profile_id uuid,p_request_id uuid,p_packet jsonb)returns jsonb language sql security invoker set search_path='' as $$select communication_evidence_review_private.confirm_review(p_tenant_id,p_actor_profile_id,p_request_id,p_packet)$$;
revoke all on function communication_evidence_review_private.review_immutable(),communication_evidence_review_private.review_source(uuid,uuid),communication_evidence_review_private.review_original(uuid),communication_evidence_review_private.read_review_page(uuid,uuid,timestamptz,uuid,integer),communication_evidence_review_private.commit_review(jsonb),communication_evidence_review_private.confirm_review(uuid,uuid,uuid,jsonb)from public,anon,authenticated;
revoke all on function public.web_read_communication_evidence_review_page(uuid,uuid,timestamptz,uuid,integer),public.web_commit_communication_evidence_review(jsonb),public.web_confirm_communication_evidence_review(uuid,uuid,uuid,jsonb)from public,anon;
grant execute on function communication_evidence_review_private.read_review_page(uuid,uuid,timestamptz,uuid,integer),communication_evidence_review_private.commit_review(jsonb),communication_evidence_review_private.confirm_review(uuid,uuid,uuid,jsonb),public.web_read_communication_evidence_review_page(uuid,uuid,timestamptz,uuid,integer),public.web_commit_communication_evidence_review(jsonb),public.web_confirm_communication_evidence_review(uuid,uuid,uuid,jsonb)to authenticated;
commit;
